1	/**
2	 * Scroll plumbing for the landing phone.
3	 *
4	 * These hooks deliberately measure their own scroll position instead of taking
5	 * a feed from landingRuntime.ts. Keeping the demo self-contained means wiring
6	 * it into the page is a one-line swap rather than a second set of edits to a
7	 * 1400-line runtime, and it gives the demo an honest `destroy()` story: every
8	 * listener and observer here is owned by a component and torn down with it
9	 * (§7.7).
10	 *
11	 * Work stops whenever the story is off screen or the tab is hidden (§6 rule 9).
12	 */
13	import { useEffect, useRef, useState } from 'react';
14	
15	/** True once the element is within `margin` of the viewport. Never flips back. */
16	export function useApproaching<T extends Element>(margin = '600px'): [React.RefObject<T>, boolean] {
17	  const ref = useRef<T>(null);
18	  const [near, setNear] = useState(false);
19	
20	  useEffect(() => {
21	    const el = ref.current;
22	    if (!el || near) return;
23	    if (typeof IntersectionObserver === 'undefined') {
24	      setNear(true);
25	      return;
26	    }
27	    const io = new IntersectionObserver(
28	      (entries) => {
29	        if (entries.some((e) => e.isIntersecting)) {
30	          setNear(true);
31	          io.disconnect();
32	        }
33	      },
34	      { rootMargin: margin },
35	    );
36	    io.observe(el);
37	    return () => io.disconnect();
38	  }, [margin, near]);
39	
40	  return [ref, near];
41	}
42	
43	/**
44	 * Whether the element is on screen right now.
45	 *
46	 * Unlike `useApproaching` this flips both ways and lets Save-Data wait for true
47	 * visibility before fetching. Scroll progress itself cannot be gated on it: a
48	 * jump straight past the story can cross no observer threshold, which would
49	 * leave the phone stranded on a stale frame.
50	 *
51	 */
52	export function useOnScreen<T extends Element>(ref: React.RefObject<T>): boolean {
53	  const [visible, setVisible] = useState(false);
54	
55	  useEffect(() => {
56	    const el = ref.current;
57	    if (!el) return;
58	    if (typeof IntersectionObserver === 'undefined') {
59	      setVisible(true);
60	      return;
61	    }
62	    const io = new IntersectionObserver((entries) => {
63	      setVisible(entries.some((e) => e.isIntersecting));
64	    });
65	    io.observe(el);
66	    return () => io.disconnect();
67	  }, [ref]);
68	
69	  return visible;
70	}
71	
72	/**
73	 * Progress of an element through the viewport, 0 → 1.
74	 *
75	 * Rounded to a small grid before it reaches React: the scene controller only
76	 * cares about milestone boundaries, so there is no reason to re-render on
77	 * sub-pixel scroll deltas.
78	 *
79	 * `trackSelector` names the element that actually travels. It exists because
80	 * the landing page pins the phone inside a `position: sticky` viewport: the
81	 * phone itself never moves relative to the viewport, so measuring it yields a
82	 * step function rather than a story. The tall scroll container around it
83	 * (`#tp-story-wrap`) is what scrolls, and measuring it reproduces the runtime's
84	 * own `(scrollY - storyTop) / storyLen` exactly.
85	 */
86	export function useStoryProgress<T extends Element>(
87	  ref: React.RefObject<T>,
88	  active = true,
89	  trackSelector?: string,
90	): number {
91	  const [progress, setProgress] = useState(0);
92	
93	  useEffect(() => {
94	    const anchor = ref.current;
95	    if (!anchor || !active) return;
96	    // Prefer the ancestor: a landing page rendered twice would otherwise have
97	    // both phones measuring the first match in the document.
98	    const el = trackSelector
99	      ? anchor.closest(trackSelector) ?? document.querySelector(trackSelector)
100	      : anchor;
101	    if (!el) return;
102	
103	    let frame = 0;
104	
105	    /*
106	     * Deliberately not gated on "is the story visible".
107	     *
108	     * Gating there strands the phone. An IntersectionObserver only fires when
109	     * the intersection ratio crosses a threshold, so scrolling from above the
110	     * story to below it in one jump — a tall landing page, a hash link, an
111	     * end key — goes 0 → 0 and fires nothing at all. Progress would then stay
112	     * frozen wherever it was, leaving the phone on scene 1 while the page sits
113	     * past scene 8.
114	     *
115	     * The reading itself is one clamped rect measurement, coalesced to one per
116	     * frame. §6 rule 9 is still satisfied where it counts: outside the story
117	     * the value pins to exactly 0 or 1, so `setProgress` no-ops and neither
118	     * React nor any scene does work.
119	     */
120	    const measure = () => {
121	      frame = 0;
122	      if (document.hidden) return;
123	      const rect = el.getBoundingClientRect();
124	      const travel = rect.height - window.innerHeight;
125	      const raw = travel > 0 ? -rect.top / travel : rect.top <= 0 ? 1 : 0;
126	      const next = Math.round(Math.min(1, Math.max(0, raw)) * 2000) / 2000;
127	      setProgress((prev) => (prev === next ? prev : next));
128	    };
129	
130	    const schedule = () => {
131	      if (frame) return;
132	      frame = requestAnimationFrame(measure);
133	    };
134	
135	    // Catches movement that fires no scroll event — a resize, a lazy image
136	    // above the story, the sticky viewport settling after layout.
137	    const io =
138	      typeof IntersectionObserver === 'undefined'
139	        ? null
140	        : new IntersectionObserver(() => schedule(), { rootMargin: '100px' });
141	    io?.observe(el);
142	
143	    window.addEventListener('scroll', schedule, { passive: true });
144	    window.addEventListener('resize', schedule, { passive: true });
145	    document.addEventListener('visibilitychange', schedule);
146	    measure();
147	
148	    return () => {
149	      if (frame) cancelAnimationFrame(frame);
150	      io?.disconnect();
151	      window.removeEventListener('scroll', schedule);
152	      window.removeEventListener('resize', schedule);
153	      document.removeEventListener('visibilitychange', schedule);
154	    };
155	  }, [ref, active, trackSelector]);
156	
157	  return progress;
158	}
159	
160	/**
161	 * Viewers who asked for less: reduced motion, or Save-Data. Both get finished
162	 * frames instead of the build-up, and Save-Data additionally suppresses the
163	 * prefetch (§6 rule 2).
164	 */
165	export function useStillPreference(): { reducedMotion: boolean; saveData: boolean } {
166	  const [state, setState] = useState({ reducedMotion: false, saveData: false });
167	
168	  useEffect(() => {
169	    const conn = (navigator as Navigator & { connection?: { saveData?: boolean } }).connection;
170	    const saveData = Boolean(conn?.saveData);
171	
172	    if (typeof window.matchMedia !== 'function') {
173	      setState({ reducedMotion: false, saveData });
174	      return;
175	    }
176	    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
177	    const sync = () => setState({ reducedMotion: mq.matches, saveData });
178	    sync();
179	    mq.addEventListener('change', sync);
180	    return () => mq.removeEventListener('change', sync);
181	  }, []);
182	
183	  return state;
184	}
