1	/**
2	 * Scroll-contract tests for the landing phone demo.
3	 *
4	 * The plan's §3.2 scroll requirements are behavioural promises that are easy to
5	 * break by accident and expensive to check by hand in a browser. Because the
6	 * controller is pure arithmetic over progress, they can be asserted directly.
7	 */
8	import {
9	  SCENE_ORDER,
10	  ZONE_COUNT,
11	  createSceneController,
12	  finalState,
13	  resolveState,
14	  sameState,
15	  sceneAtProgress,
16	  stepAtProgress,
17	} from '@/pages/landing-phone/reducer';
18	import { SCENES, stepsFor } from '@/pages/landing-phone/scenes/registry';
19	import { INDUSTRY_SCENE, SCENE_STEPS } from '@/pages/landing-phone/manifest';
20	import { INDUSTRY_PHONE } from '@/pages/DeferredLandingPhone';
21	import type { LandingPhoneScene, LandingPhoneState } from '@/pages/landing-phone/types';
22	
23	const key = (s: LandingPhoneState) => `${s.scene}#${s.step}`;
24	
25	/** Every state the story passes through, scanning finely enough to miss nothing. */
26	function scan(from: number, to: number, samples = 20_000): LandingPhoneState[] {
27	  const out: LandingPhoneState[] = [];
28	  for (let i = 0; i <= samples; i++) {
29	    const p = from + ((to - from) * i) / samples;
30	    const s = resolveState(p, stepsFor);
31	    if (out.length === 0 || !sameState(out[out.length - 1], s)) out.push(s);
32	  }
33	  return out;
34	}
35	
36	describe('scene registry', () => {
37	  it('registers exactly one scene per story zone', () => {
38	    expect(SCENE_ORDER).toHaveLength(ZONE_COUNT);
39	    expect(Object.keys(SCENES).sort()).toEqual([...SCENE_ORDER].sort());
40	  });
41	
42	  /**
43	   * manifest.ts duplicates the step counts so landing-page.tsx can size the
44	   * Industries phone without importing the registry (which would drag all eight
45	   * scenes into the main chunk). Its docblock has always claimed this test
46	   * guards the duplication; until now it did not, and the two silently drifted.
47	   *
48	   * Drift is not cosmetic: the Industries phone rests on `SCENE_STEPS - 1`, so a
49	   * stale count leaves a tab sitting on a half-finished workflow.
50	   */
51	  it('keeps the landing page manifest in step with the registry', () => {
52	    for (const id of SCENE_ORDER) {
53	      expect(SCENE_STEPS[id]).toBe(SCENES[id].steps);
54	    }
55	    expect(Object.keys(SCENE_STEPS).sort()).toEqual([...SCENE_ORDER].sort());
56	  });
57	
58	  it('points every Industries tab at a registered scene', () => {
59	    for (const scene of Object.values(INDUSTRY_SCENE)) {
60	      expect(SCENES[scene]).toBeDefined();
61	    }
62	  });
63	
64	  it('keeps the eager Industries metadata in step with the lazy registry', () => {
65	    for (const { scene, steps } of Object.values(INDUSTRY_PHONE)) {
66	      expect(SCENES[scene]).toBeDefined();
67	      expect(steps).toBe(SCENES[scene].steps);
68	    }
69	  });
70	
71	  it('gives every scene at least one milestone and a matching id', () => {
72	    for (const id of SCENE_ORDER) {
73	      const def = SCENES[id];
74	      expect(def.id).toBe(id);
75	      expect(def.steps).toBeGreaterThan(0);
76	      expect(def.label.length).toBeGreaterThan(0);
77	    }
78	  });
79	});
80	
81	describe('forward scrolling', () => {
82	  it('visits every scene in story order', () => {
83	    const scenes = scan(0, 1).map((s) => s.scene);
84	    const firstSeen: LandingPhoneScene[] = [];
85	    for (const s of scenes) if (!firstSeen.includes(s)) firstSeen.push(s);
86	    expect(firstSeen).toEqual([...SCENE_ORDER]);
87	  });
88	
89	  it('visits every milestone of every scene, in order and without skipping', () => {
90	    const seen = scan(0, 1).map(key);
91	    const expected: string[] = [];
92	    for (const id of SCENE_ORDER) {
93	      for (let step = 0; step < SCENES[id].steps; step++) expected.push(`${id}#${step}`);
94	    }
95	    expect(seen).toEqual(expected);
96	  });
97	});
98	
99	describe('backward scrolling', () => {
100	  it('rewinds through exactly the forward states, reversed', () => {
101	    const forward = scan(0, 1).map(key);
102	    const backward = scan(1, 0).map(key);
103	    expect(backward).toEqual([...forward].reverse());
104	  });
105	});
106	
107	describe('zone entry and exit', () => {
108	  it('starts each zone at its own step 0', () => {
109	    for (let zone = 0; zone < ZONE_COUNT; zone++) {
110	      const state = resolveState(zone / ZONE_COUNT, stepsFor);
111	      expect(state.scene).toBe(SCENE_ORDER[zone]);
112	      expect(state.step).toBe(0);
113	    }
114	  });
115	
116	  it('finishes each zone on its last milestone', () => {
117	    for (let zone = 0; zone < ZONE_COUNT; zone++) {
118	      const endOfZone = (zone + 1) / ZONE_COUNT - 1e-9;
119	      const state = resolveState(endOfZone, stepsFor);
120	      expect(state.scene).toBe(SCENE_ORDER[zone]);
121	      expect(state.step).toBe(SCENES[state.scene].steps - 1);
122	    }
123	  });
124	});
125	
126	describe('jumping and clamping', () => {
127	  it('maps any progress to exactly one state', () => {
128	    for (const p of [0, 0.137, 0.5, 0.625, 0.99, 1]) {
129	      expect(resolveState(p, stepsFor)).toEqual(resolveState(p, stepsFor));
130	    }
131	  });
132	
133	  it('clamps out-of-range and non-finite progress instead of throwing', () => {
134	    expect(resolveState(-4, stepsFor)).toEqual({ scene: SCENE_ORDER[0], step: 0 });
135	    expect(resolveState(Number.NaN, stepsFor)).toEqual({ scene: SCENE_ORDER[0], step: 0 });
136	    const last = SCENE_ORDER[ZONE_COUNT - 1];
137	    expect(resolveState(9, stepsFor)).toEqual({ scene: last, step: SCENES[last].steps - 1 });
138	  });
139	
140	  it('never returns a step outside its scene', () => {
141	    for (let i = 0; i <= 5000; i++) {
142	      const s = resolveState(i / 5000, stepsFor);
143	      expect(s.step).toBeGreaterThanOrEqual(0);
144	      expect(s.step).toBeLessThan(SCENES[s.scene].steps);
145	    }
146	  });
147	});
148	
149	describe('reduced motion and Save-Data', () => {
150	  it('lands on the finished frame of a scene rather than its build-up', () => {
151	    for (const id of SCENE_ORDER) {
152	      expect(finalState(id, stepsFor)).toEqual({ scene: id, step: SCENES[id].steps - 1 });
153	    }
154	  });
155	});
156	
157	describe('controller', () => {
158	  it('reports only genuine milestone changes', () => {
159	    const c = createSceneController(stepsFor);
160	    const first = c.update(0.0001);
161	    expect(first).toBeNull(); // already at overview#0
162	
163	    let emissions = 0;
164	    for (let i = 0; i <= 4000; i++) if (c.update(i / 4000)) emissions++;
165	
166	    const distinct = scan(0, 1).length;
167	    expect(emissions).toBe(distinct - 1); // every change once, no repeats
168	  });
169	
170	  it('accepts direct selection for the Industries tabs', () => {
171	    const c = createSceneController(stepsFor);
172	    expect(c.set({ scene: 'retail-sale', step: 2 })).toEqual({ scene: 'retail-sale', step: 2 });
173	    expect(c.set({ scene: 'retail-sale', step: 2 })).toBeNull();
174	    expect(c.state).toEqual({ scene: 'retail-sale', step: 2 });
175	  });
176	});
177	
178	describe('determinism', () => {
179	  it('does not depend on the clock', () => {
180	    const before = resolveState(0.42, stepsFor);
181	    const realNow = Date.now;
182	    try {
