1	#!/usr/bin/env node
2	/**
3	 * Overlap and spacing audit for the landing page.
4	 *
5	 * Reports, per viewport and per act:
6	 *   • pairs of interactive elements whose hit areas genuinely collide
7	 *     (neither contains the other) — one of them is unclickable;
8	 *   • interactive elements pushed outside the viewport horizontally;
9	 *   • interactive elements that touch or sit closer than a comfortable gap.
10	 *
11	 * Read-only: it changes nothing, it just measures. Run before and after a
12	 * layout fix to prove the fix.
13	 *
14	 *   node scripts/audit-landing-overlaps.mjs
15	 *   node scripts/audit-landing-overlaps.mjs --json
16	 */
17	import { createRequire } from 'node:module';
18	
19	const require = createRequire(import.meta.url);
20	const { chromium } = require('playwright-core');
21	
22	const arg = (name, fallback = null) => {
23	  const i = process.argv.indexOf(`--${name}`);
24	  return i >= 0 && process.argv[i + 1] && !process.argv[i + 1].startsWith('--') ? process.argv[i + 1] : fallback;
25	};
26	
27	const BASE_URL = arg('url', process.env.LANDING_URL ?? 'http://127.0.0.1:5000');
28	const CHROMIUM =
29	  process.env.CHROMIUM_PATH ??
30	  '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium';
31	const AS_JSON = process.argv.includes('--json');
32	
33	const VIEWPORTS = [
34	  { name: 'desktop', width: 1440, height: 900 },
35	  { name: 'tablet', width: 1180, height: 820 },
36	  { name: 'mobile', width: 390, height: 844 },
37	];
38	
39	/** Below this, two controls read as one blob and are easy to mis-tap. */
40	const MIN_GAP = 8;
41	
42	/**
43	 * Runs in the page. Returns every collision, near-miss and overflow it can see.
44	 *
45	 * Only judges controls currently inside the viewport band. Measuring the whole
46	 * document at once looks cheaper but lies: the cinematic phone is inside a
47	 * `position: sticky` viewport and the mobile Industries phone is `display: none`
48	 * until its reveal tab is tapped, so an off-screen rect is not the rect a reader
49	 * ever sees.
50	 */
51	function measure(minGap) {
52	  const sel = 'a[href], button, [role="button"], input, select, textarea, [tabindex]:not([tabindex="-1"])';
53	  const vh = window.innerHeight;
54	  const nodes = Array.from(document.querySelectorAll(sel)).filter((el) => {
55	    const cs = getComputedStyle(el);
56	    if (cs.display === 'none' || cs.visibility === 'hidden' || Number(cs.opacity) === 0) return false;
57	    if (cs.pointerEvents === 'none') return false;
58	    const r = el.getBoundingClientRect();
59	    if (r.width < 2 || r.height < 2) return false;
60	    return r.bottom > -40 && r.top < vh + 40;
61	  });
62	
63	  const describe = (el) => {
64	    const r = el.getBoundingClientRect();
65	    const label = (el.getAttribute('aria-label') || el.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 34);
66	    const owner = el.closest('section[id], div[id^="tp-"]');
67	    return {
68	      tag: el.tagName.toLowerCase(),
69	      cls: (typeof el.className === 'string' ? el.className : '').split(' ').filter(Boolean).slice(0, 2).join('.'),
70	      id: el.id || null,
71	      act: owner ? owner.id : null,
72	      label,
73	      x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height),
74	    };
75	  };
76	
77	  const overlaps = [];
78	  const tight = [];
79	  const offscreen = [];
80	  const vw = window.innerWidth;
81	
82	  for (let i = 0; i < nodes.length; i++) {
83	    const a = nodes[i];
84	    const ra = a.getBoundingClientRect();
85	    if (ra.left < -1 || ra.right > vw + 1) offscreen.push({ ...describe(a), vw });
86	
87	    for (let j = i + 1; j < nodes.length; j++) {
88	      const b = nodes[j];
89	      // A control inside another control is a nesting question, not an overlap.
90	      if (a.contains(b) || b.contains(a)) continue;
91	      const rb = b.getBoundingClientRect();
92	
93	      const ox = Math.min(ra.right, rb.right) - Math.max(ra.left, rb.left);
94	      const oy = Math.min(ra.bottom, rb.bottom) - Math.max(ra.top, rb.top);
95	
96	      if (ox > 1 && oy > 1) {
97	        overlaps.push({ a: describe(a), b: describe(b), overlapW: Math.round(ox), overlapH: Math.round(oy) });
98	      } else if (ox > 1 && oy <= 1 && oy > -minGap) {
99	        // Near-miss: they share one axis and are closer than a comfortable gap
100	        // on the other, so they read as one blob and are easy to mis-tap.
101	        tight.push({ a: describe(a), b: describe(b), gap: Math.round(-oy), axis: 'vertical' });
102	      } else if (oy > 1 && ox <= 1 && ox > -minGap) {
103	        tight.push({ a: describe(a), b: describe(b), gap: Math.round(-ox), axis: 'horizontal' });
104	      }
105	    }
106	  }
107	  return { overlaps, tight, offscreen, count: nodes.length };
108	}
109	
110	const ACTS = ['tp-hero', 'tp-story-wrap', 'tp-industries', 'tp-pricing', 'tp-contact'];
111	
112	async function run() {
113	  const browser = await chromium.launch({ executablePath: CHROMIUM, args: ['--no-sandbox'] });
114	  const report = [];
115	
116	  for (const vp of VIEWPORTS) {
117	    const page = await browser.newPage({ viewport: { width: vp.width, height: vp.height } });
118	    await page.goto(BASE_URL, { waitUntil: 'networkidle' });
119	    await page.waitForTimeout(1200);
120	
121	    const seenPairs = new Set();
122	    const vpReport = { viewport: vp.name, overlaps: [], tight: [], offscreen: [], stations: [] };
123	
124	    const keyOf = (o) => `${o.a.tag}.${o.a.cls}#${o.a.label}|${o.b.tag}.${o.b.cls}#${o.b.label}`;
125	
126	    const sampleHere = async (station) => {
127	      const res = await page.evaluate(measure, MIN_GAP);
128	      if (!res) return;
129	      vpReport.stations.push({ station, controls: res.count });
130	      for (const o of res.overlaps) {
131	        if (seenPairs.has(keyOf(o))) continue;
