import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { chromium } = require('playwright-core');
const CHROMIUM = '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium';
const OUT = '/tmp/claude-1000/-home-runner-workspace/c91138e1-3508-4c6d-8e3b-6b0c7689d01a/scratchpad';

const browser = await chromium.launch({ executablePath: CHROMIUM, args: ['--no-sandbox'] });
for (const vp of [{ name: 'desktop', width: 1440, height: 900 }, { name: 'mobile', width: 390, height: 844 }]) {
  const page = await browser.newPage({ viewport: { width: vp.width, height: vp.height } });
  await page.goto('http://127.0.0.1:5000', { waitUntil: 'networkidle' });
  await page.evaluate(() => document.getElementById('tp-industries')?.scrollIntoView({ block: 'center', behavior: 'instant' }));
  await page.waitForTimeout(2500);
  const info = await page.evaluate(() => {
    const q = (s) => document.querySelector(s);
    const box = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
    const frame = q('#tp-industries .tp-app-frame');
    const scaleHost = q('#tp-industries .tp-phone-scale');
    return {
      phone: box(q('#tp-industries .tp-phone')),
      scaleHost: box(scaleHost),
      scaleHostClientW: scaleHost?.clientWidth,
      frame: box(frame),
      frameTransform: frame ? getComputedStyle(frame).transform : null,
      frameInline: frame ? frame.getAttribute('style') : null,
      frameOuterTag: frame ? frame.tagName + '.' + frame.className : null,
      live: box(q('.tp-phone-live')),
      tiltInner: q('.tp-tilt-inner') ? getComputedStyle(q('.tp-tilt-inner')).transform : null,
      demoScene: q('#tp-industries [data-demo-scene]')?.getAttribute('data-demo-scene'),
      nestedButtons: Array.from(document.querySelectorAll('#tp-industries button')).map((b) => ({
        label: (b.getAttribute('aria-label') || b.textContent || '').trim().slice(0, 30),
        cls: b.className, ...box(b),
        parentChain: (() => { let p = b.parentElement, out = []; while (p && out.length < 4) { out.push(p.tagName + (p.className ? '.' + String(p.className).split(' ')[0] : '')); p = p.parentElement; } return out.join(' < '); })(),
      })),
    };
  });
  console.log(vp.name, JSON.stringify(info, null, 2));
  await page.screenshot({ path: `${OUT}/ind-${vp.name}.png` });
  await page.close();
}
await browser.close();

